(x, y, t) => {
  const cx = 240, cy = 120;
  let wx = Math.sin(x*0.02+t*0.3)*15+Math.cos(y*0.015-t*0.2)*10;
  let wy = Math.cos(y*0.02-t*0.25)*15+Math.sin(x*0.018+t*0.35)*10;
  wx += Math.sin((x+y)*0.01+t*0.5)*8;
  wy += Math.cos((x-y)*0.012-t*0.45)*8;
  const sx = x+wx, sy = y+wy;
  const src = [
    [160+Math.sin(t*0.6)*100,80+Math.cos(t*0.4)*50,0.08,2.0],
    [320+Math.cos(t*0.5)*100,160+Math.sin(t*0.7)*50,0.1,1.7],
    [240+Math.sin(t*0.3+2)*140,120+Math.cos(t*0.5+1)*90,0.06,2.3],
    [120+Math.cos(t*0.8+1)*80,180+Math.sin(t*0.6+3)*60,0.12,1.5],
    [360+Math.sin(t*0.4+4)*90,60+Math.cos(t*0.9+2)*70,0.07,2.6],
    [240+Math.cos(t*0.35+5)*120,200+Math.sin(t*0.55)*80,0.09,1.9],
    [80+Math.sin(t*0.45+3)*70,40+Math.cos(t*0.65+2)*55,0.11,2.1],
    [400+Math.cos(t*0.55+1)*60,200+Math.sin(t*0.75+4)*45,0.13,1.8],
    [200+Math.sin(t*0.25+6)*110,220+Math.cos(t*0.45+5)*70,0.075,2.4]
  ];
  let aS=0,iS=0,mS=0;
  for(const[sX,sY,f,sp]of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    const w=Math.sin(d*0.03-t*0.8)*0.5+0.5;
    aS+=Math.sin(d*f-t*sp)*(0.7+w*0.3);
    iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5);
    mS+=Math.sin(d*f*1.3-t*sp*0.4+2.8)*0.5;
  }
  const act=aS/9,inh=iS/9,mod=mS/9;
  let bg=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2;
  bg+=Math.sin((sx+sy)*0.12+t*2.5)*0.2+Math.sin((sx-sy)*0.1-t*2)*0.2;
  bg+=Math.sin(sx*0.06+Math.sin(sy*0.05+t)*2+t)*0.15;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2),ang=Math.atan2(sy-cy,sx-cx);
  let spiral=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.4;
  spiral+=Math.sin(dist*0.08+ang*2-t*2.2)*0.2;
  const pulse=Math.sin(dist*0.03-t*1.8)*Math.exp(-dist*0.003)*0.4;
  let r1=Math.tanh((act-inh*0.7+bg*0.3+spiral+pulse)*2.2);
  let r2=Math.tanh((inh-act*0.5+mod+spiral*0.5)*2.0);
  const cross=Math.tanh((r1*r2+r1-r2)*1.8);
  const cell=Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;
  const voronoi=()=>{let md=99;for(let i=0;i<9;i++){const px=src[i][0]+Math.sin(i*2.4+t*0.3)*20,py=src[i][1]+Math.cos(i*1.8+t*0.4)*20;const d=Math.sqrt((sx-px)**2+(sy-py)**2);if(d<md)md=d;}return md;};
  const vEdge=Math.tanh((voronoi()-8)*0.8)*0.25;
  const blend=cross*0.55+r1*0.2+cell*0.15+vEdge*0.1;
  const v=blend*0.5+0.5;
  const pal=[[5,12,52],[12,42,92],[18,78,118],[24,120,130],[55,155,125],[140,180,100],[210,185,75],[220,150,60],[200,105,65],[170,60,70],[120,35,65],[60,18,55],[5,12,52]];
  const idx=v*(pal.length-1),i=Math.min(idx|0,pal.length-2),f=idx-i;
  const lum=0.8+Math.sin(cross*Math.PI)*0.25;
  const edge=Math.abs(cross)>0.75?1.2:Math.abs(cross)>0.5?1.08:1.0;
  const shimmer=Math.sin(sx*0.3+sy*0.2+t*4)*0.03+1;
  const ca=(r2-r1)*0.015;
  return[
    Math.min(255,Math.max(0,(pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge*shimmer+ca*80))|0,
    Math.min(255,Math.max(0,(pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge*shimmer))|0,
    Math.min(255,Math.max(0,(pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge*shimmer-ca*80))|0
  ];
}
